#include <bits/stdc++.h>
using namespace std;

struct Pos {
    int r, c;
    Pos(int _r = 0, int _c = 0) : r(_r), c(_c) {}
};

int N, T;
vector<string> B;
vector<vector<int> > D1, D2;
int dr[4] = {-1, 0, 0, 1};
int dc[4] = {0, -1, 1, 0};

void bfs_z(const Pos& src) {
    D1.assign(N + 2, vector<int>(N + 2, -1));
    deque<Pos> q;
    D1[src.r][src.c] = 0;
    q.push_back(src);
    while (!q.empty()) {
        Pos u = q.front();
        q.pop_front();
        for (int k = 0; k < 4; ++k) {
            int nr = u.r + dr[k], nc = u.c + dc[k];
            if (B[nr][nc] != '.') continue;
            if (D1[nr][nc] >= 0) continue;
            D1[nr][nc] = D1[u.r][u.c] + 1;
            q.push_back(Pos(nr, nc));
        }
    }
}

void bfs_source(const Pos& src) {
    D2.assign(N + 2, vector<int>(N + 2, -1));
    deque<Pos> q;
    D2[src.r][src.c] = 0;
    q.push_back(src);
    while (!q.empty()) {
        Pos u = q.front();
        q.pop_front();
        if (D1[u.r][u.c] >= 0 && D2[u.r][u.c] >= D1[u.r][u.c]) continue;
        for (int k = 0; k < 4; ++k) {
            int nr = u.r + dr[k], nc = u.c + dc[k];
            if (B[nr][nc] != '.') continue;
            if (D2[nr][nc] >= 0) continue;
            if (D1[nr][nc] >= 0 && D1[nr][nc] < D2[u.r][u.c] + 1) continue;
            D2[nr][nc] = D2[u.r][u.c] + 1;
            q.push_back(Pos(nr, nc));
        }
    }
}

int scaling_maxflow(int s, int t, vector<vector<int> > cap) {
    int n = (int)cap.size();
    int flow = 0;

    for (int scale = 1 << 30; scale > 0; scale >>= 1) {
        while (true) {
            vector<int> par(n, -1);
            queue<int> q;
            par[s] = s;
            q.push(s);
            while (!q.empty() && par[t] == -1) {
                int u = q.front();
                q.pop();
                for (int v = 0; v < n; ++v) {
                    if (par[v] == -1 && cap[u][v] >= scale) {
                        par[v] = u;
                        q.push(v);
                        if (v == t) break;
                    }
                }
            }
            if (par[t] == -1) break;

            int add = INT_MAX;
            for (int v = t; v != s; v = par[v])
                add = min(add, cap[par[v]][v]);
            for (int v = t; v != s; v = par[v]) {
                cap[par[v]][v] -= add;
                cap[v][par[v]] += add;
            }
            flow += add;
        }
    }
    return flow;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> T;
    B.assign(N + 2, string(N + 2, '#'));

    string line;
    for (int r = 1; r <= N; ++r) {
        cin >> line;
        for (int c = 1; c <= N; ++c) B[r][c] = line[c - 1];
    }
    vector<string> B1 = B;

    vector<string> B2(N + 2, string(N + 2, '#'));
    for (int r = 1; r <= N; ++r) {
        cin >> line;
        for (int c = 1; c <= N; ++c) B2[r][c] = line[c - 1];
    }

    vector<Pos> scientists, capsules;
    Pos z;
    for (int r = 1; r <= N; ++r) {
        for (int c = 1; c <= N; ++c) {
            char ch = B[r][c];
            if (ch >= '0' && ch <= '9') {
                if (ch > '0') scientists.push_back(Pos(r, c));
                B[r][c] = '.';
            } else if (ch == 'Z') {
                z = Pos(r, c);
                B[r][c] = '.';
            }
            char ch2 = B2[r][c];
            if (ch2 >= '0' && ch2 <= '9' && ch2 > '0')
                capsules.push_back(Pos(r, c));
        }
    }

    bfs_z(z);

    int nS = (int)scientists.size();
    int nC = (int)capsules.size();
    int SRC = 0;
    int SINK = nS + nC + 1;
    vector<vector<int> > cap(SINK + 1, vector<int>(SINK + 1, 0));
    const int INF = 98765432;

    for (int i = 0; i < nS; ++i) {
        const Pos& s = scientists[i];
        cap[SRC][i + 1] += B1[s.r][s.c] - '0';
    }
    for (int j = 0; j < nC; ++j) {
        const Pos& c = capsules[j];
        cap[nS + j + 1][SINK] += B2[c.r][c.c] - '0';
    }

    for (int i = 0; i < nS; ++i) {
        const Pos& s = scientists[i];
        bfs_source(s);
        for (int j = 0; j < nC; ++j) {
            const Pos& c = capsules[j];
            if (D2[c.r][c.c] >= 0 && D2[c.r][c.c] <= T)
                cap[i + 1][nS + j + 1] = INF;
        }
    }

    cout << scaling_maxflow(SRC, SINK, cap) << '\n';
    return 0;
}
